use std::fs;
use std::path::Path;

use sha2::{Digest, Sha256};

#[path = "scalar_browser_ci_contract/historical_builder.rs"]
mod historical_builder;

fn digest_without_checked_value_cursor_budget(graph: &str) -> String {
    let parsed: serde_json::Value = serde_json::from_str(graph).unwrap();
    let digest_field = format!(",\"graph_digest\":{}", parsed["graph_digest"]);
    assert_eq!(graph.matches(&digest_field).count(), 1);
    let payload = graph.replacen(&digest_field, "", 1);
    let hash = |payload: &str| {
        let mut hasher = Sha256::new();
        hasher.update(b"semaprax.project-semantic-graph.artifact-digest.v1\0");
        hasher.update((payload.len() as u64).to_le_bytes());
        hasher.update(payload.as_bytes());
        let hex: String = hasher
            .finalize()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect();
        format!("sha256:{hex}")
    };
    assert_eq!(hash(&payload), parsed["graph_digest"]);
    // Three checked modules each reserve a 257-entry cursor stack. On the
    // supported 64-bit hosts its tagged reference plus index occupy 24 bytes.
    // Replaying the whole payload after removing only that debit against a
    // pinned digest proves the source, declarations, edges and other budgets
    // stayed frozen at this version. The pinned digests were re-taken when
    // imported functions began charging their retained stub plus the peak
    // transient provider clone, when the canonical prelude gained standard
    // collections, and when import result ownership became explicit. The latest
    // pins retain that cursor subtraction and account for the independently
    // proven 21,577-byte retained identity-carrier budget reduction.
    let current = parsed["budget"]["used_builder_bytes"].as_u64().unwrap();
    let previous = current.checked_sub(3 * 257 * 24).unwrap();
    let field = format!("\"used_builder_bytes\":{current}");
    assert_eq!(payload.matches(&field).count(), 1);
    let previous_payload =
        payload.replacen(&field, &format!("\"used_builder_bytes\":{previous}"), 1);
    hash(&previous_payload)
}

fn read(root: &Path, relative: &str) -> String {
    fs::read_to_string(root.join(relative)).unwrap_or_else(|error| {
        panic!("cannot read {relative}: {error}");
    })
}

#[test]
fn browser_known_answers_match_authenticated_baseline_and_rename_graphs() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let runner = read(
        root,
        "platform-tests/wasm-scalar-browser-v1/test-fixtures.mjs",
    );
    let fields = [
        "project_revision",
        "workspace_revision",
        "project_graph_digest",
    ];
    let expected = fields.map(|field| {
        let prefix = format!("{field}: \"");
        let values: Vec<_> = runner
            .lines()
            .filter_map(|line| line.trim().strip_prefix(&prefix)?.strip_suffix("\","))
            .collect();
        assert_eq!(
            values.len(),
            2,
            "exact baseline and renamed {field} answers"
        );
        values
    });
    struct Fixture(std::path::PathBuf);
    impl Drop for Fixture {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }
    let fixture = Fixture(std::env::temp_dir().join(format!(
        "spx-browser-graph-known-answers-{}",
        std::process::id()
    )));
    fs::create_dir(&fixture.0).unwrap();
    fs::create_dir(fixture.0.join("src")).unwrap();
    let fixture_root = fixture.0.canonicalize().unwrap();
    let source_root = root.join("examples/calculator-project");
    for path in [
        "semaprax.toml",
        "src/app.spx",
        "src/core.spx",
        "src/tests.spx",
    ] {
        fs::copy(source_root.join(path), fixture_root.join(path)).unwrap();
    }
    let mut previous_digests = Vec::new();
    for (index, name) in ["baseline", "renamed"].into_iter().enumerate() {
        if index == 1 {
            let path = fixture_root.join("src/core.spx");
            let original = fs::read_to_string(&path).unwrap();
            let renamed = original.replace("\nfn add(", "\nfn sum(");
            assert_ne!(original, renamed);
            fs::write(path, renamed).unwrap();
        }
        semaprax::project::with_authenticated_project(
            &fixture_root.join("semaprax.toml"),
            |snapshot| {
                let revision = snapshot.retain_revision();
                if let Some(directory) = std::env::var_os("SEMAPRAX_PRELUDE_PIN_CAPTURE_DIR") {
                    use std::io::Write as _;
                    let path =
                        std::path::Path::new(&directory).join(format!("calculator-{name}.json"));
                    let mut file = std::fs::OpenOptions::new()
                        .write(true)
                        .create_new(true)
                        .open(path)
                        .expect("fresh calculator pin evidence file");
                    file.write_all(revision.semantic_graph().as_bytes())
                        .expect("capture complete actual calculator graph");
                }
                previous_digests.push(historical_builder::current67b_digest(revision.semantic_graph()));
                historical_builder::current67b_drift_controls(revision.semantic_graph());
                let actual = [
                    revision.project_revision(),
                    revision.workspace_revision(),
                    revision.semantic_graph_digest(),
                ];
                for (field, value) in actual.into_iter().enumerate() {
                    assert_eq!(
                        value, expected[field][index],
                        "{} fixture {name}",
                        fields[field]
                    );
                }
                Ok(())
            },
        )
        .unwrap();
    }
    assert_eq!(
        previous_digests,
        [
            "sha256:489f02ed298c2d35433d6c9f811ccc26c50ce90117b3976a862b40aff11129b8",
            "sha256:ccb0ec81a00f3890ec2fe87af8d0f801970a1a397eeb55fe115e83dab02188ba",
        ],
        "only the checked value cursor budget changed in the browser graphs"
    );
}

