        (
            runner,
            "9d948189ad72776458ac959b7573da65f5b2803f6689671fbb1319ea8df74b3b",
        ),
    ] {
        assert_eq!(
            format!(
                "{:x}",
                semaprax::digest_hex::LowerHex(Sha256::digest(source.as_bytes()))
            ),
